        $db->table('transfer_account_payments')->insert(['origin_id'=>$bank->id,'origin_type'=>BankAccount::class,
            'destiny_id'=>$inactive->id,'destiny_type'=>BankAccount::class,'currency_type_id'=>null,'amount'=>'1',
