        self::assertSame('Bs. 0.10',$filtered['07:VES']['total']);
        $voided=collect($controller->recordsTotal(\Illuminate\Http\Request::create('/','GET',['state_type_id'=>'11'])))
            ->keyBy(fn($row)=>$row['document_type_id'].':'.$row['currency_type_id']);
