        $file=(new \Maatwebsite\Excel\Writer($temp))->export(new \Modules\Report\Exports\PosCashDocumentsExport($report,\App\Models\Tenant\Company::firstOrFail()),\Maatwebsite\Excel\Excel::XLSX);
