                    self::assertStringStartsWith('%PDF-',$ticket,"$design $format $type");
                    $extract=new \Symfony\Component\Process\Process(['pdftotext','-layout',$ticketPath,'-']); $extract->mustRun();
                    $text=preg_replace('/\s+/u',' ',trim($extract->getOutput()));
