                    if ($type==='01' && in_array($design,['default','modern-2027'],true)) self::assertStringContainsString('AJUSTE DE TEXTO EN EL TICKET',$text);
                    if ($type==='01' && $design==='nrus') self::assertStringContainsString('Productos: 4 UND',$text);
