            self::assertContains('VES 46.40',$visible);
            self::assertContains(['user:'.$input['user_id'].':VES','total_commision','46.4','232','5'],
                $book->getSheetByName('Fracciones exactas')->toArray(null,true,false,false));
            $book->disconnectWorksheets();
        } finally {$file->delete();}
