        $fraction=['n'=>'1','d'=>'3'];
        $snapshot=\App\Support\Exact\Decimal::snapshot(['quantity'=>'1','unit_value'=>$fraction,'unit_price'=>$fraction,
            'total_value'=>$fraction,'total'=>$fraction,'total_discount'=>'0','total_igv'=>'0']);
